// src/scene/shader-lib/wgsl/chunks/common/frag/tonemapping/tonemappingAces2.js
var tonemappingAces2_default2 = (
  /* wgsl */
  `
// ACES approximation by Stephen Hill

// sRGB => XYZ => D65_2_D60 => AP1 => RRT_SAT
const ACESInputMat: mat3x3f = mat3x3f(
    vec3f(0.59719, 0.35458, 0.04823),
    vec3f(0.07600, 0.90834, 0.01566),
    vec3f(0.02840, 0.13383, 0.83777)
);

// ODT_SAT => XYZ => D60_2_D65 => sRGB
const ACESOutputMat: mat3x3f = mat3x3f(
    vec3f( 1.60475, -0.53108, -0.07367),
    vec3f(-0.10208,  1.10813, -0.00605),
    vec3f(-0.00327, -0.07276,  1.07602)
);

fn RRTAndODTFit(v: vec3f) -> vec3f {
    let a: vec3f = v * (v + vec3f(0.0245786)) - vec3f(0.000090537);
    let b: vec3f = v * (vec3f(0.983729) * v + vec3f(0.4329510)) + vec3f(0.238081);
    return a / b;
}

fn toneMap(color: vec3f) -> vec3f {
    var c: vec3f = color * (getExposure() / 0.6);
    c = c * ACESInputMat;

    // Apply RRT and ODT
    c = RRTAndODTFit(c);
    c = c * ACESOutputMat;

    // Clamp to [0, 1]
    return clamp(c, vec3f(0.0), vec3f(1.0));
}
`
);

// src/scene/shader-lib/wgsl/chunks/common/frag/tonemapping/tonemappingFilmic.js
var tonemappingFilmic_default2 = (
  /* wgsl */
  `
const A: f32 = 0.15;
const B: f32 = 0.50;
const C: f32 = 0.10;
const D: f32 = 0.20;
const E: f32 = 0.02;
const F: f32 = 0.30;
const W: f32 = 11.2;

fn uncharted2Tonemap(x: vec3f) -> vec3f {
    return ((x * (A * x + C * B) + D * E) / (x * (A * x + B) + D * F)) - vec3f(E / F);
}

fn toneMap(color: vec3f) -> vec3f {
    var c: vec3f = uncharted2Tonemap(color * getExposure());
    let whiteScale: vec3f = vec3f(1.0) / uncharted2Tonemap(vec3f(W, W, W));
    c *= whiteScale;
    return c;
}
`
);

// src/scene/shader-lib/wgsl/chunks/common/frag/tonemapping/tonemappingHejl.js
var tonemappingHejl_default2 = (
  /* wgsl */
  `
fn toneMap(color: vec3f) -> vec3f {
    let A: f32 = 0.22;
    let B: f32 = 0.3;
    let C: f32 = 0.1;
    let D: f32 = 0.2;
    let E: f32 = 0.01;
    let F: f32 = 0.3;
    let Scl: f32 = 1.25;

    let adjusted_color = color * getExposure();
    let h = max(vec3f(0.0), adjusted_color - vec3f(0.004));

    return (h * ((Scl * A) * h + Scl * vec3f(C * B)) + Scl * vec3f(D * E)) /
           (h * (A * h + vec3f(B)) + vec3f(D * F)) -
           Scl * vec3f(E / F);
}
`
);

